using Microsoft.Data.Sqlite;

namespace Sentinel.Store;

// P26: the rebuildable half of the split. Every table here can be
// regenerated by scanning (fingerprints, census, orphan verdicts,
// dead-link notes, scan-policy markers), so this file may be wiped
// or quarantined without touching Passport history. Implementation
// moved verbatim from the single-file store; only the schema gate
// is new (versioned + atomic, shared contract with PassportDb).
public sealed class FingerprintDb : IDisposable
{
    public const int SchemaVersion = 1;

    private readonly SqliteConnection _conn;
    private readonly object _gate = new();
    private SqliteTransaction? _bulk;
    private bool _disposed;

    public string DbPath { get; }

    public FingerprintDb(string dbPath)
    {
        DbPath = dbPath;
        string? dir = Path.GetDirectoryName(dbPath);
        if (!string.IsNullOrEmpty(dir))
        {
            Directory.CreateDirectory(dir);
        }

        _conn = new SqliteConnection($"Data Source={dbPath}");
        try
        {
            _conn.Open();
            using (var busy = _conn.CreateCommand())
            {
                busy.CommandText = "PRAGMA busy_timeout = 5000;";
                busy.ExecuteNonQuery();
            }

            EnsureSchema();
        }
        catch
        {
            // A08: a throwing constructor must not leak its open
            // handle — the abandoned lock blocked quarantine moves
            // and later opens of the same file. Pooling is on, so
            // Dispose alone parks the handle in the pool; clear it.
            _conn.Dispose();
            SqliteConnection.ClearAllPools();
            throw;
        }
    }

    private void EnsureSchema()
    {
        long version;
        using (var cmd = _conn.CreateCommand())
        {
            cmd.CommandText = "PRAGMA user_version;";
            version = (long)(cmd.ExecuteScalar() ?? 0L);
        }

        if (version > SchemaVersion)
        {
            throw new InvalidOperationException(
                $"Fingerprint store schema v{version} is newer than this build (v{SchemaVersion}).");
        }

        if (version == SchemaVersion)
        {
            return;
        }

        using var tx = _conn.BeginTransaction();
        try
        {
            if (version < 1)
            {
                ApplyV1(tx);
            }

            using (var stamp = _conn.CreateCommand())
            {
                stamp.Transaction = tx;
                stamp.CommandText = $"PRAGMA user_version = {SchemaVersion};";
                stamp.ExecuteNonQuery();
            }

            tx.Commit();
        }
        catch
        {
            tx.Rollback();
            throw;
        }
    }

    private void ApplyV1(SqliteTransaction tx)
    {
        using var cmd = _conn.CreateCommand();
        cmd.Transaction = tx;
        cmd.CommandText = """
            CREATE TABLE IF NOT EXISTS Fingerprints(
                Path TEXT PRIMARY KEY,
                Size INTEGER NOT NULL,
                MTimeUtcTicks INTEGER NOT NULL,
                Hash TEXT NULL,
                LastSeenGeneration INTEGER NOT NULL,
                Tier TEXT NULL,
                Regrowth TEXT NULL,
                AttrFlags INTEGER NOT NULL DEFAULT 0,
                ClassGen INTEGER NOT NULL DEFAULT 0);
            CREATE TABLE IF NOT EXISTS Meta(
                Key TEXT PRIMARY KEY,
                Value TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS OrphanDirs(
                Dir TEXT PRIMARY KEY,
                YoungestTicks INTEGER NOT NULL,
                Signals TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS DirStats(
                Dir TEXT PRIMARY KEY,
                DirectFiles INTEGER NOT NULL,
                DirectSubdirs INTEGER NOT NULL,
                DirectUnverified INTEGER NOT NULL DEFAULT 0,
                MtimeTicks INTEGER NOT NULL,
                Generation INTEGER NOT NULL);
            CREATE TABLE IF NOT EXISTS DeadLinks(
                Path TEXT PRIMARY KEY,
                Target TEXT NOT NULL);
            CREATE INDEX IF NOT EXISTS IX_Fingerprints_Gen
                ON Fingerprints(LastSeenGeneration);
            """;
        cmd.ExecuteNonQuery();
        // Tier/Hash indexes live in MigrateFingerprints: creating them
        // here would fail on pre-P22 tables that lack the columns.
        MigrateFingerprints(tx);
    }

    // P22 additive migration for pre-P22 Fingerprint tables. Old rows
    // get NULL tier (unclassified: the classifier pass fills them),
    // zero flags, ClassGen 0. Never backfills guesses.
    private void MigrateFingerprints(SqliteTransaction tx)
    {
        using var pragma = _conn.CreateCommand();
        pragma.Transaction = tx;
        pragma.CommandText = "SELECT name FROM pragma_table_info('Fingerprints');";
        var columns = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        using (var reader = pragma.ExecuteReader())
        {
            while (reader.Read())
            {
                columns.Add(reader.GetString(0));
            }
        }

        string[] adds =
        [
            "ALTER TABLE Fingerprints ADD COLUMN Tier TEXT NULL;",
            "ALTER TABLE Fingerprints ADD COLUMN Regrowth TEXT NULL;",
            "ALTER TABLE Fingerprints ADD COLUMN AttrFlags INTEGER NOT NULL DEFAULT 0;",
            "ALTER TABLE Fingerprints ADD COLUMN ClassGen INTEGER NOT NULL DEFAULT 0;",
        ];
        string[] names = ["Tier", "Regrowth", "AttrFlags", "ClassGen"];
        for (int i = 0; i < names.Length; i++)
        {
            if (!columns.Contains(names[i]))
            {
                using var alter = _conn.CreateCommand();
                alter.Transaction = tx;
                alter.CommandText = adds[i];
                alter.ExecuteNonQuery();
            }
        }

        using var idx = _conn.CreateCommand();
        idx.Transaction = tx;
        idx.CommandText = """
            CREATE INDEX IF NOT EXISTS IX_Fingerprints_TierSize
                ON Fingerprints(Tier, Size DESC);
            CREATE INDEX IF NOT EXISTS IX_Fingerprints_Hash
                ON Fingerprints(Hash);
            """;
        idx.ExecuteNonQuery();
    }

    public string? GetMeta(string key)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = "SELECT Value FROM Meta WHERE Key = $key;";
            cmd.Parameters.AddWithValue("$key", key);
            var value = cmd.ExecuteScalar();
            return value is null or DBNull ? null : Convert.ToString(value);
        }
    }

    public void SetMeta(string key, string value)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                INSERT INTO Meta(Key, Value) VALUES ($key, $value)
                ON CONFLICT(Key) DO UPDATE SET Value = excluded.Value;
                """;
            cmd.Parameters.AddWithValue("$key", key);
            cmd.Parameters.AddWithValue("$value", value);
            cmd.ExecuteNonQuery();
        }
    }

    // A08: side-effect-free health probe. Opens read-only, so a
    // corrupt store is never mutated by the check itself. Returns
    // null when the store reads healthy, an explanation otherwise.
    // A missing file is "healthy" (nothing stored yet).
    public static string? ProbeHealth(string dbPath)
    {
        if (!File.Exists(dbPath))
        {
            return null;
        }

        try
        {
            // Pooling=false: Dispose must truly close the handle,
            // or the pooled handle blocks later exclusive opens
            // and quarantine moves of this same file.
            using var conn = new SqliteConnection($"Data Source={dbPath};Mode=ReadOnly;Pooling=false");
            conn.Open();
            using var cmd = conn.CreateCommand();
            foreach (string table in new[]
                { "Fingerprints", "Meta", "OrphanDirs", "DirStats", "DeadLinks" })
            {
                cmd.CommandText = $"SELECT COUNT(*) FROM {table};";
                cmd.ExecuteScalar();
            }

            return null;
        }
        catch (Exception ex)
        {
            return ex.GetType().Name + ": " + ex.Message.Split('\n')[0];
        }
    }

    // Bulk mode: one transaction per scan run. Without this, every
    // fingerprint round-trip commits separately and a 500k-file drive
    // would take hours (measured: 74 files/s before, see 07 record).
    public void BeginBulk()
    {
        lock (_gate)
        {
            _bulk ??= _conn.BeginTransaction();
        }
    }

    public void EndBulk(bool commit = true)
    {
        lock (_gate)
        {
            if (_bulk is null)
            {
                return;
            }

            try
            {
                if (commit)
                {
                    _bulk.Commit();
                }
                else
                {
                    _bulk.Rollback();
                }
            }
            finally
            {
                _bulk.Dispose();
                _bulk = null;
            }
        }
    }

    private void Enlist(SqliteCommand cmd)
    {
        cmd.Transaction = _bulk;
    }

    public Fingerprint? GetFingerprint(string path)
    {
        lock (_gate)
        {
            return GetFingerprintLocked(path);
        }
    }

    // Bounded inventory aggregates for the Cleaner page. The page
    // classifies the largest N with stated coverage — never the
    // whole table on the UI path.
    public long CountFingerprints()
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = "SELECT COUNT(*) FROM Fingerprints;";
            return (long)(cmd.ExecuteScalar() ?? 0L);
        }
    }

    public long SumFingerprintBytes()
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = "SELECT COALESCE(SUM(Size), 0) FROM Fingerprints;";
            return (long)(cmd.ExecuteScalar() ?? 0L);
        }
    }

    public IReadOnlyList<Fingerprint> ListLargestFingerprints(int limit = 5000)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                SELECT Path, Size, MTimeUtcTicks, Hash, LastSeenGeneration,
                    Tier, Regrowth, AttrFlags, ClassGen
                FROM Fingerprints ORDER BY Size DESC LIMIT $limit;
                """;
            cmd.Parameters.AddWithValue("$limit", Math.Clamp(limit, 1, 20000));
            using var reader = cmd.ExecuteReader();
            var rows = new List<Fingerprint>();
            while (reader.Read())
            {
                rows.Add(ReadFingerprint(reader));
            }

            return rows;
        }
    }

    // Deletion reconciliation (P1-03): after a scope's enumeration
    // completes, rows under root unseen in this generation are
    // deleted files — UNLESS they sit on or under a gap path.
    // Inaccessible, excluded, and linked areas are NEVER inferred
    // deleted (a root-level gap therefore disables the purge for
    // that root). Unrelated roots are untouched. Returns the
    // purged count. Call only on successful enumeration, inside
    // the scan's bulk transaction.
    public int DeleteFingerprintsNotSeenIn(
        string root, int generation, IReadOnlyList<string> gapPaths)
    {
        lock (_gate)
        {
            string fullRoot = NormalizeDir(root);
            var gapSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var g in gapPaths)
            {
                gapSet.Add(NormalizePath(g));
            }

            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                SELECT Path FROM Fingerprints
                WHERE (Path = $root OR Path LIKE $prefix ESCAPE '\')
                AND LastSeenGeneration < $gen;
                """;
            cmd.Parameters.AddWithValue("$root", fullRoot);
            cmd.Parameters.AddWithValue("$prefix", EscapeLike(fullRoot + Path.DirectorySeparatorChar) + "%");
            cmd.Parameters.AddWithValue("$gen", generation);
            var stale = new List<string>();
            using (var reader = cmd.ExecuteReader())
            {
                while (reader.Read())
                {
                    stale.Add(reader.GetString(0));
                }
            }

            int deleted = 0;
            foreach (var path in stale)
            {
                if (IsOnOrUnderGap(NormalizePath(path), fullRoot, gapSet))
                {
                    continue;
                }

                using var del = _conn.CreateCommand();
                Enlist(del);
                del.CommandText = "DELETE FROM Fingerprints WHERE Path = $path;";
                del.Parameters.AddWithValue("$path", path);
                deleted += del.ExecuteNonQuery();
                // P23: a deleted shortcut loses its dead-target note
                // with it — no lingering claims about gone files.
                using var delLink = _conn.CreateCommand();
                Enlist(delLink);
                delLink.CommandText = "DELETE FROM DeadLinks WHERE Path = $path;";
                delLink.Parameters.AddWithValue("$path", path);
                delLink.ExecuteNonQuery();
            }

            return deleted;
        }
    }

    private static string NormalizePath(string path)
    {
        try
        {
            return Path.GetFullPath(path)
                .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        }
        catch (Exception) when (path is not null)
        {
            return path;
        }
    }

    private static string NormalizeDir(string root) => NormalizePath(root);

    private static bool IsOnOrUnderGap(string path, string fullRoot, HashSet<string> gapSet)
    {
        string? current = path;
        while (current is not null && current.Length >= fullRoot.Length)
        {
            if (gapSet.Contains(current))
            {
                return true;
            }

            current = Path.GetDirectoryName(current);
        }

        return false;
    }

    private static string EscapeLike(string value) =>
        value.Replace(@"\", @"\\").Replace("%", @"\%").Replace("_", @"\_");

    // Fingerprint-cache rebuild (corrupt-DB recovery offer): drops
    // cached rows; the next scan re-discovers everything. Run
    // history is kept. User-confirmed, app-data-only.
    public void ClearFingerprints()
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = "DELETE FROM Fingerprints;";
            cmd.ExecuteNonQuery();
        }
    }

    private Fingerprint? GetFingerprintLocked(string path)
    {
        using var cmd = _conn.CreateCommand();
        Enlist(cmd);
        cmd.CommandText = """
            SELECT Path, Size, MTimeUtcTicks, Hash, LastSeenGeneration,
                Tier, Regrowth, AttrFlags, ClassGen
            FROM Fingerprints WHERE Path = $path;
            """;
        cmd.Parameters.AddWithValue("$path", path);
        using var reader = cmd.ExecuteReader();
        if (!reader.Read())
        {
            return null;
        }

        return ReadFingerprint(reader);
    }

    public void UpsertFingerprint(
        string path, long size, long mtimeTicks, string? hash, int generation, int attrFlags = 0,
        string? tier = null, string? regrowth = null, int classGen = 0, bool hasTier = false)
    {
        lock (_gate)
        {
            UpsertFingerprintLocked(path, size, mtimeTicks, hash, generation, attrFlags,
                tier, regrowth, classGen, hasTier);
        }
    }

    private void UpsertFingerprintLocked(
        string path, long size, long mtimeTicks, string? hash, int generation, int attrFlags,
        string? tier, string? regrowth, int classGen, bool hasTier)
    {
        using var cmd = _conn.CreateCommand();
        Enlist(cmd);
        // A freshly computed tier (scan-time classify) is written as
        // given — it was computed from this exact stat. Without one,
        // a stat change invalidates the stored tier (reclassify pass
        // refills it); an unchanged stat keeps it.
        cmd.CommandText = """
            INSERT INTO Fingerprints(Path, Size, MTimeUtcTicks, Hash, LastSeenGeneration, AttrFlags,
                Tier, Regrowth, ClassGen)
            VALUES ($path, $size, $mtime, $hash, $gen, $flags, $tier, $regrowth, $classGen)
            ON CONFLICT(Path) DO UPDATE SET
                Size = excluded.Size,
                MTimeUtcTicks = excluded.MTimeUtcTicks,
                Hash = excluded.Hash,
                LastSeenGeneration = excluded.LastSeenGeneration,
                AttrFlags = excluded.AttrFlags,
                Tier = CASE WHEN $hasTier != 0 THEN excluded.Tier
                    WHEN Fingerprints.Size != excluded.Size
                    OR Fingerprints.MTimeUtcTicks != excluded.MTimeUtcTicks
                    THEN NULL ELSE Fingerprints.Tier END,
                Regrowth = CASE WHEN $hasTier != 0 THEN excluded.Regrowth
                    WHEN Fingerprints.Size != excluded.Size
                    OR Fingerprints.MTimeUtcTicks != excluded.MTimeUtcTicks
                    THEN NULL ELSE Fingerprints.Regrowth END,
                ClassGen = CASE WHEN $hasTier != 0 THEN excluded.ClassGen
                    WHEN Fingerprints.Size != excluded.Size
                    OR Fingerprints.MTimeUtcTicks != excluded.MTimeUtcTicks
                    THEN 0 ELSE Fingerprints.ClassGen END;
            """;
        cmd.Parameters.AddWithValue("$path", path);
        cmd.Parameters.AddWithValue("$size", size);
        cmd.Parameters.AddWithValue("$mtime", mtimeTicks);
        cmd.Parameters.AddWithValue("$hash", (object?)hash ?? DBNull.Value);
        cmd.Parameters.AddWithValue("$gen", generation);
        cmd.Parameters.AddWithValue("$flags", attrFlags);
        cmd.Parameters.AddWithValue("$tier", (object?)tier ?? DBNull.Value);
        cmd.Parameters.AddWithValue("$regrowth", (object?)regrowth ?? DBNull.Value);
        cmd.Parameters.AddWithValue("$classGen", classGen);
        cmd.Parameters.AddWithValue("$hasTier", hasTier ? 1 : 0);
        cmd.ExecuteNonQuery();
    }

    // P22: one bounded write for a classified row. ClassGen stamps the
    // scan generation whose stat the tier was computed from.
    public void SetClassification(string path, string tier, string? regrowth, int classGen)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                UPDATE Fingerprints
                SET Tier = $tier, Regrowth = $regrowth, ClassGen = $gen
                WHERE Path = $path;
                """;
            cmd.Parameters.AddWithValue("$tier", tier);
            cmd.Parameters.AddWithValue("$regrowth", (object?)regrowth ?? DBNull.Value);
            cmd.Parameters.AddWithValue("$gen", classGen);
            cmd.Parameters.AddWithValue("$path", path);
            cmd.ExecuteNonQuery();
        }
    }

    // P22: one keyset chunk of rows still needing classification
    // (never classified, or invalidated by a stat change). The caller
    // loops with afterPath = last path until a short page, classifying
    // and writing each chunk back: bounded memory at any table size,
    // and the reader is closed before any write (SQLite forbids a
    // write under an open reader on the same connection).
    public IReadOnlyList<Fingerprint> QueryUnclassifiedChunk(
        string? afterPath, int limit, int classGenFloor)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                SELECT Path, Size, MTimeUtcTicks, Hash, LastSeenGeneration,
                    Tier, Regrowth, AttrFlags, ClassGen
                FROM Fingerprints
                WHERE (Tier IS NULL OR ClassGen < $floor)
                AND ($after IS NULL OR Path > $after)
                ORDER BY Path LIMIT $limit;
                """;
            cmd.Parameters.AddWithValue("$floor", classGenFloor);
            cmd.Parameters.AddWithValue("$after", (object?)afterPath ?? DBNull.Value);
            cmd.Parameters.AddWithValue("$limit", Math.Clamp(limit, 1, 10000));
            using var reader = cmd.ExecuteReader();
            var rows = new List<Fingerprint>();
            while (reader.Read())
            {
                rows.Add(ReadFingerprint(reader));
            }

            return rows;
        }
    }

    // P22: how many rows the classifier pass must visit (progress
    // honesty: the service reports done/total, never a spinner).
    public long CountUnclassified(int classGenFloor)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                SELECT COUNT(*) FROM Fingerprints
                WHERE Tier IS NULL OR ClassGen < $floor;
                """;
            cmd.Parameters.AddWithValue("$floor", classGenFloor);
            return (long)(cmd.ExecuteScalar() ?? 0L);
        }
    }

    // P22: chunked classification write-back. One transaction per
    // chunk; a failed chunk rolls back without touching others.
    public void UpdateClassifications(
        IReadOnlyList<(string Path, string Tier, string? Regrowth, int ClassGen)> chunk)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            // A chunk of our own only outside a scan bulk; inside one
            // (never the case on the classify path) enlist instead of
            // nesting, which SQLite forbids.
            using var tx = _bulk is null ? _conn.BeginTransaction() : null;
            if (tx is not null)
            {
                cmd.Transaction = tx;
            }

            cmd.CommandText = """
                UPDATE Fingerprints
                SET Tier = $tier, Regrowth = $regrowth, ClassGen = $gen
                WHERE Path = $path;
                """;
            var pTier = cmd.Parameters.Add("$tier", Microsoft.Data.Sqlite.SqliteType.Text);
            var pReg = cmd.Parameters.Add("$regrowth", Microsoft.Data.Sqlite.SqliteType.Text);
            var pGen = cmd.Parameters.Add("$gen", Microsoft.Data.Sqlite.SqliteType.Integer);
            var pPath = cmd.Parameters.Add("$path", Microsoft.Data.Sqlite.SqliteType.Text);
            foreach (var row in chunk)
            {
                pTier.Value = row.Tier;
                pReg.Value = (object?)row.Regrowth ?? DBNull.Value;
                pGen.Value = row.ClassGen;
                pPath.Value = row.Path;
                cmd.ExecuteNonQuery();
            }

            tx?.Commit();
        }
    }

    private static Fingerprint ReadFingerprint(Microsoft.Data.Sqlite.SqliteDataReader reader)
    {
        return new Fingerprint(
            reader.GetString(0),
            reader.GetInt64(1),
            reader.GetInt64(2),
            reader.IsDBNull(3) ? null : reader.GetString(3),
            reader.GetInt32(4),
            reader.IsDBNull(5) ? null : reader.GetString(5),
            reader.IsDBNull(6) ? null : reader.GetString(6),
            reader.GetInt32(7),
            reader.GetInt32(8));
    }

    // P22: one bounded page over the stated inventory. Every page
    // carries its own totals + generation stamp, so the UI can say
    // "1-100 of 12,304 (generation 7)" instead of showing a silent
    // sample. OFFSET paging with a stable order; a scan running
    // mid-browse can shift rows — the stamp makes that visible.
    public InventoryPage QueryInventoryPage(InventoryQuery q)
    {
        lock (_gate)
        {
            var where = new List<string>();
            var args = new List<(string Name, object Value)>();
            if (!string.IsNullOrEmpty(q.Tier))
            {
                where.Add("Tier = $tier");
                args.Add(("$tier", q.Tier));
            }

            if (q.MinSize is not null)
            {
                where.Add("Size >= $min");
                args.Add(("$min", q.MinSize.Value));
            }

            if (q.MaxSize is not null)
            {
                where.Add("Size <= $max");
                args.Add(("$max", q.MaxSize.Value));
            }

            if (!string.IsNullOrWhiteSpace(q.Extension))
            {
                string ext = q.Extension.StartsWith('.') ? q.Extension : "." + q.Extension;
                where.Add("Path LIKE $ext ESCAPE '\\'");
                args.Add(("$ext", "%" + EscapeLike(ext)));
            }

            if (!string.IsNullOrWhiteSpace(q.NameContains))
            {
                where.Add("Path LIKE $needle ESCAPE '\\'");
                args.Add(("$needle", "%" + EscapeLike(q.NameContains.Trim()) + "%"));
            }

            var prefixes = (q.DirPrefixes ?? [])
                .Where(p => !string.IsNullOrWhiteSpace(p)).ToList();
            if (prefixes.Count > 0)
            {
                var ors = new List<string>();
                for (int i = 0; i < prefixes.Count; i++)
                {
                    string full = NormalizeDir(prefixes[i]);
                    ors.Add($"(Path = $d{i} OR Path LIKE $dp{i} ESCAPE '\\')");
                    args.Add(($"$d{i}", full));
                    args.Add(($"$dp{i}", EscapeLike(full + Path.DirectorySeparatorChar) + "%"));
                }

                where.Add("(" + string.Join(" OR ", ors) + ")");
            }

            if (q.HashMissingOnly)
            {
                where.Add("Hash IS NULL");
            }

            if (q.RegrowingOnly)
            {
                where.Add("Regrowth IS NOT NULL");
            }

            string filter = where.Count == 0 ? string.Empty : "WHERE " + string.Join(" AND ", where);
            string order = q.Sort == "name"
                ? "ORDER BY Path ASC"
                : "ORDER BY Size DESC, Path ASC";
            int limit = Math.Clamp(q.Limit, 1, 1000);
            int offset = Math.Max(0, q.Offset);

            long total;
            long bytes;
            int maxGen;
            using (var cmd = _conn.CreateCommand())
            {
                Enlist(cmd);
                cmd.CommandText =
                    $"SELECT COUNT(*), COALESCE(SUM(Size), 0), COALESCE(MAX(LastSeenGeneration), 0) FROM Fingerprints {filter};";
                foreach (var a in args)
                {
                    cmd.Parameters.AddWithValue(a.Name, a.Value);
                }

                using var reader = cmd.ExecuteReader();
                reader.Read();
                total = reader.GetInt64(0);
                bytes = reader.GetInt64(1);
                maxGen = reader.GetInt32(2);
            }

            var rows = new List<Fingerprint>();
            using (var cmd = _conn.CreateCommand())
            {
                Enlist(cmd);
                cmd.CommandText =
                    $"SELECT Path, Size, MTimeUtcTicks, Hash, LastSeenGeneration, Tier, Regrowth, AttrFlags, ClassGen FROM Fingerprints {filter} {order} LIMIT $limit OFFSET $offset;";
                foreach (var a in args)
                {
                    cmd.Parameters.AddWithValue(a.Name, a.Value);
                }

                cmd.Parameters.AddWithValue("$limit", limit);
                cmd.Parameters.AddWithValue("$offset", offset);
                using var reader = cmd.ExecuteReader();
                while (reader.Read())
                {
                    rows.Add(ReadFingerprint(reader));
                }
            }

            return new InventoryPage(rows, total, bytes, maxGen);
        }
    }

    // P22: tier strip over the FULL retained inventory (replaces the
    // largest-5000 tier counts). NULL tier = not yet classified.
    public IReadOnlyList<TierGroup> CountGroupByTier()
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                SELECT COALESCE(Tier, ''), COUNT(*), COALESCE(SUM(Size), 0)
                FROM Fingerprints GROUP BY COALESCE(Tier, '');
                """;
            using var reader = cmd.ExecuteReader();
            var groups = new List<TierGroup>();
            while (reader.Read())
            {
                groups.Add(new TierGroup(reader.GetString(0), reader.GetInt64(1), reader.GetInt64(2)));
            }

            return groups;
        }
    }

    // P22: treemap buckets in ONE pass. Prefixes are (key, dir) pairs in
    // priority order; rows matching none land in the restKey bucket, so
    // the buckets always partition the stated total (design §7: no
    // parent+child double count). Bytes are counted logical sizes.
    public IReadOnlyDictionary<string, (long Files, long Bytes)> SumBuckets(
        IReadOnlyList<(string Key, string Dir)> buckets, string restKey)
    {
        lock (_gate)
        {
            var whens = new List<string>();
            var args = new List<(string Name, object Value)>();
            for (int i = 0; i < buckets.Count; i++)
            {
                string full = NormalizeDir(buckets[i].Dir);
                whens.Add($"WHEN Path = $r{i} OR Path LIKE $p{i} ESCAPE '\\' THEN $k{i}");
                args.Add(($"$r{i}", full));
                args.Add(($"$p{i}", EscapeLike(full + Path.DirectorySeparatorChar) + "%"));
                args.Add(($"$k{i}", buckets[i].Key));
            }

            string caseExpr = whens.Count == 0
                ? "$rest"
                : $"CASE {string.Join(" ", whens)} ELSE $rest END";
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText =
                $"SELECT {caseExpr}, COUNT(*), COALESCE(SUM(Size), 0) FROM Fingerprints GROUP BY 1;";
            foreach (var a in args)
            {
                cmd.Parameters.AddWithValue(a.Name, a.Value);
            }

            cmd.Parameters.AddWithValue("$rest", restKey);
            using var reader = cmd.ExecuteReader();
            var result = new Dictionary<string, (long Files, long Bytes)>(StringComparer.Ordinal);
            while (reader.Read())
            {
                result[reader.GetString(0)] = (reader.GetInt64(1), reader.GetInt64(2));
            }

            return result;
        }
    }

    // P22: immediate children of one directory with rolled-up sizes.
    // Aggregates inside the read loop: no row list is ever built, so
    // even a million-file folder stays a bounded pass. Subdirectory
    // bytes include their whole subtrees (one honest number each).
    public IReadOnlyList<ChildRollup> QueryChildRollup(string dirPrefix, CancellationToken ct)
    {
        lock (_gate)
        {
            string full = NormalizeDir(dirPrefix);
            string withSep = full + Path.DirectorySeparatorChar;
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                SELECT Path, Size FROM Fingerprints
                WHERE Path LIKE $prefix ESCAPE '\';
                """;
            cmd.Parameters.AddWithValue("$prefix", EscapeLike(withSep) + "%");
            using var reader = cmd.ExecuteReader();
            var files = new List<(string Name, long Size)>();
            var dirs = new Dictionary<string, (long Files, long Bytes)>(StringComparer.OrdinalIgnoreCase);
            while (reader.Read())
            {
                ct.ThrowIfCancellationRequested();
                string path = reader.GetString(0);
                long size = reader.GetInt64(1);
                if (!path.StartsWith(withSep, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                string rest = path.Substring(withSep.Length);
                int sep = rest.IndexOf(Path.DirectorySeparatorChar);
                if (sep < 0)
                {
                    int alt = rest.IndexOf(Path.AltDirectorySeparatorChar);
                    sep = alt;
                }

                if (sep < 0)
                {
                    files.Add((rest, size));
                }
                else
                {
                    string child = rest.Substring(0, sep);
                    if (dirs.TryGetValue(child, out var acc))
                    {
                        dirs[child] = (acc.Files + 1, acc.Bytes + size);
                    }
                    else
                    {
                        dirs[child] = (1, size);
                    }
                }
            }

            var result = new List<ChildRollup>();
            foreach (var d in dirs.OrderByDescending(kv => kv.Value.Bytes))
            {
                result.Add(new ChildRollup(d.Key, true, d.Value.Files, d.Value.Bytes));
            }

            foreach (var f in files.OrderByDescending(f => f.Size))
            {
                result.Add(new ChildRollup(f.Name, false, 1, f.Size));
            }

            return result;
        }
    }

    // P22: duplicate sets over the FULL inventory, paged by wasted
    // bytes. Hash NULL rows (never hashed, failed, placeholders) are
    // excluded — "same unknown" is not a duplicate finding.
    public (IReadOnlyList<DuplicateSet> Sets, long TotalSets, long TotalWasted) QueryDuplicateSets(
        int limit, int offset, string? nameContains = null,
        IReadOnlyList<string>? dirPrefixes = null)
    {
        lock (_gate)
        {
            limit = Math.Clamp(limit, 1, 200);
            offset = Math.Max(0, offset);
            // Search/scope compose over the full set WITHOUT changing
            // what a set IS: filters apply to member rows before
            // grouping would split sets apart, so they apply to the
            // group's concatenated paths instead (a set matches when
            // ANY member matches). Totals always describe the match.
            var args = new List<(string Name, object Value)>();
            var havings = new List<string> { "COUNT(*) > 1" };
            if (!string.IsNullOrWhiteSpace(nameContains))
            {
                havings.Add("GROUP_CONCAT(Path, CHAR(31)) LIKE $needle ESCAPE '\\'");
                args.Add(("$needle", "%" + EscapeLike(nameContains.Trim()) + "%"));
            }

            var prefixes = (dirPrefixes ?? [])
                .Where(p => !string.IsNullOrWhiteSpace(p)).ToList();
            if (prefixes.Count > 0)
            {
                var ors = new List<string>();
                for (int i = 0; i < prefixes.Count; i++)
                {
                    string full = NormalizeDir(prefixes[i]);
                    ors.Add($"SUM(CASE WHEN Path = $d{i} OR Path LIKE $dp{i} ESCAPE '\\' THEN 1 ELSE 0 END) > 0");
                    args.Add(($"$d{i}", full));
                    args.Add(($"$dp{i}", EscapeLike(full + Path.DirectorySeparatorChar) + "%"));
                }

                havings.Add("(" + string.Join(" OR ", ors) + ")");
            }

            string having = "HAVING " + string.Join(" AND ", havings);
            long totalSets;
            long totalWasted;
            using (var cmd = _conn.CreateCommand())
            {
                Enlist(cmd);
                cmd.CommandText = $"""
                    SELECT COUNT(*), COALESCE(SUM((C - 1) * S), 0) FROM (
                        SELECT COUNT(*) AS C, MIN(Size) AS S FROM Fingerprints
                        WHERE Hash IS NOT NULL GROUP BY Hash {having});
                    """;
                foreach (var a in args)
                {
                    cmd.Parameters.AddWithValue(a.Name, a.Value);
                }

                using var reader = cmd.ExecuteReader();
                reader.Read();
                totalSets = reader.GetInt64(0);
                totalWasted = reader.GetInt64(1);
            }

            var sets = new List<DuplicateSet>();
            using (var cmd = _conn.CreateCommand())
            {
                Enlist(cmd);
                cmd.CommandText = $"""
                    SELECT Hash, MIN(Size), COUNT(*),
                        GROUP_CONCAT(Path, CHAR(31))
                    FROM Fingerprints
                    WHERE Hash IS NOT NULL GROUP BY Hash {having}
                    ORDER BY (COUNT(*) - 1) * MIN(Size) DESC
                    LIMIT $limit OFFSET $offset;
                    """;
                foreach (var a in args)
                {
                    cmd.Parameters.AddWithValue(a.Name, a.Value);
                }

                cmd.Parameters.AddWithValue("$limit", limit);
                cmd.Parameters.AddWithValue("$offset", offset);
                using var reader = cmd.ExecuteReader();
                while (reader.Read())
                {
                    string packed = reader.GetString(3);
                    var paths = packed.Split((char)31).OrderBy(p => p, StringComparer.Ordinal).ToList();
                    sets.Add(new DuplicateSet(
                        reader.GetString(0), reader.GetInt64(1),
                        reader.GetInt32(2), paths));
                }
            }

            return (sets, totalSets, totalWasted);
        }
    }

    // P22: limit-reporting facts, one pass. Hash-missing counts rows
    // whose content identity is unknown (hash failed, never requested,
    // or a placeholder skipped by policy) — surfaced as one honest
    // number, not three invented ones.
    public AttrStats QueryAttrStats()
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                SELECT
                    COUNT(CASE WHEN (AttrFlags & 1) != 0 THEN 1 END),
                    COALESCE(SUM(CASE WHEN (AttrFlags & 1) != 0 THEN Size END), 0),
                    COUNT(CASE WHEN (AttrFlags & 2) != 0 THEN 1 END),
                    COALESCE(SUM(CASE WHEN (AttrFlags & 2) != 0 THEN Size END), 0),
                    COUNT(CASE WHEN Hash IS NULL THEN 1 END)
                FROM Fingerprints;
                """;
            using var reader = cmd.ExecuteReader();
            reader.Read();
            return new AttrStats(
                reader.GetInt64(0), reader.GetInt64(1),
                reader.GetInt64(2), reader.GetInt64(3),
                reader.GetInt64(4));
        }
    }

    // P22: distinct directories with youngest mtime, folded inside the
    // read loop (PK order = no sort step). Feeds the orphan pass; the
    // caller caches the verdicts per generation (see OrphanDirs table
    // notes in the classifier service) instead of re-folding per page.
    public IReadOnlyDictionary<string, long> FoldDirectoryMtimes(CancellationToken ct)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = "SELECT Path, MTimeUtcTicks FROM Fingerprints ORDER BY Path;";
            using var reader = cmd.ExecuteReader();
            var dirs = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
            while (reader.Read())
            {
                ct.ThrowIfCancellationRequested();
                string dir;
                try
                {
                    dir = Path.GetDirectoryName(reader.GetString(0)) ?? string.Empty;
                }
                catch
                {
                    continue;
                }

                if (dir.Length == 0)
                {
                    continue;
                }

                long mtime = reader.GetInt64(1);
                if (!dirs.TryGetValue(dir, out long young) || mtime > young)
                {
                    dirs[dir] = mtime;
                }
            }

            return dirs;
        }
    }

    // P22: cached orphan verdicts, paged. The cache is valid for
    // one (generation, uninstall-entries-hash) pair — the classifier
    // service owns invalidation via Meta keys OrphanGen/OrphanHash.
    public IReadOnlyList<(string Dir, long YoungestTicks, string Signals)> QueryOrphanDirs(
        int limit, int offset, out long total, string? nameContains = null,
        IReadOnlyList<string>? dirPrefixes = null)
    {
        lock (_gate)
        {
            limit = Math.Clamp(limit, 1, 500);
            offset = Math.Max(0, offset);
            var wheres = new List<string>();
            var args = new List<(string Name, object Value)>();
            if (!string.IsNullOrWhiteSpace(nameContains))
            {
                wheres.Add("Dir LIKE $needle ESCAPE '\\'");
                args.Add(("$needle", "%" + EscapeLike(nameContains.Trim()) + "%"));
            }

            var prefixes = (dirPrefixes ?? [])
                .Where(p => !string.IsNullOrWhiteSpace(p)).ToList();
            if (prefixes.Count > 0)
            {
                var ors = new List<string>();
                for (int i = 0; i < prefixes.Count; i++)
                {
                    string full = NormalizeDir(prefixes[i]);
                    ors.Add($"(Dir = $d{i} OR Dir LIKE $dp{i} ESCAPE '\\')");
                    args.Add(($"$d{i}", full));
                    args.Add(($"$dp{i}", EscapeLike(full + Path.DirectorySeparatorChar) + "%"));
                }

                wheres.Add("(" + string.Join(" OR ", ors) + ")");
            }

            string filter = wheres.Count == 0 ? string.Empty : "WHERE " + string.Join(" AND ", wheres);
            using (var cmd = _conn.CreateCommand())
            {
                Enlist(cmd);
                cmd.CommandText = $"SELECT COUNT(*) FROM OrphanDirs {filter};";
                foreach (var a in args)
                {
                    cmd.Parameters.AddWithValue(a.Name, a.Value);
                }

                total = (long)(cmd.ExecuteScalar() ?? 0L);
            }

            var rows = new List<(string Dir, long YoungestTicks, string Signals)>();
            using (var cmd = _conn.CreateCommand())
            {
                Enlist(cmd);
                cmd.CommandText = $"SELECT Dir, YoungestTicks, Signals FROM OrphanDirs {filter} ORDER BY Dir LIMIT $limit OFFSET $offset;";
                foreach (var a in args)
                {
                    cmd.Parameters.AddWithValue(a.Name, a.Value);
                }

                cmd.Parameters.AddWithValue("$limit", limit);
                cmd.Parameters.AddWithValue("$offset", offset);
                using var reader = cmd.ExecuteReader();
                while (reader.Read())
                {
                    rows.Add((reader.GetString(0), reader.GetInt64(1), reader.GetString(2)));
                }
            }

            return rows;
        }
    }

    public void ReplaceOrphanDirs(IReadOnlyList<(string Dir, long YoungestTicks, string Signals)> rows)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            using var tx = _bulk is null ? _conn.BeginTransaction() : null;
            if (tx is not null)
            {
                cmd.Transaction = tx;
            }

            cmd.CommandText = "DELETE FROM OrphanDirs;";
            cmd.ExecuteNonQuery();
            cmd.CommandText = """
                INSERT INTO OrphanDirs(Dir, YoungestTicks, Signals)
                VALUES ($dir, $ticks, $signals);
                """;
            var pDir = cmd.Parameters.Add("$dir", Microsoft.Data.Sqlite.SqliteType.Text);
            var pTicks = cmd.Parameters.Add("$ticks", Microsoft.Data.Sqlite.SqliteType.Integer);
            var pSig = cmd.Parameters.Add("$signals", Microsoft.Data.Sqlite.SqliteType.Text);
            foreach (var row in rows)
            {
                pDir.Value = row.Dir;
                pTicks.Value = row.YoungestTicks;
                pSig.Value = row.Signals;
                cmd.ExecuteNonQuery();
            }

            tx?.Commit();
        }
    }

    // P23: replaces this scope's directory census. The delete covers
    // the scope subtree only, so sibling scopes keep their rows;
    // dirs deleted since the last scan lose their rows here (there
    // is no per-dir generation reconcile — the census is rewritten
    // whole per scope per completed scan).
    public void ReplaceDirStats(
        string scopeRoot, IReadOnlyList<DirStat> rows, int generation)
    {
        lock (_gate)
        {
            string fullRoot = NormalizeDir(scopeRoot);
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            using var tx = _bulk is null ? _conn.BeginTransaction() : null;
            if (tx is not null)
            {
                cmd.Transaction = tx;
            }

            cmd.CommandText = """
                DELETE FROM DirStats
                WHERE Dir = $root OR Dir LIKE $prefix ESCAPE '\';
                """;
            cmd.Parameters.AddWithValue("$root", fullRoot);
            cmd.Parameters.AddWithValue(
                "$prefix", EscapeLike(fullRoot + Path.DirectorySeparatorChar) + "%");
            cmd.ExecuteNonQuery();

            cmd.CommandText = """
                INSERT INTO DirStats(Dir, DirectFiles, DirectSubdirs, DirectUnverified, MtimeTicks, Generation)
                VALUES ($dir, $files, $subdirs, $unverified, $mtime, $gen);
                """;
            cmd.Parameters.Clear();
            var pDir = cmd.Parameters.Add("$dir", Microsoft.Data.Sqlite.SqliteType.Text);
            var pFiles = cmd.Parameters.Add("$files", Microsoft.Data.Sqlite.SqliteType.Integer);
            var pSubdirs = cmd.Parameters.Add("$subdirs", Microsoft.Data.Sqlite.SqliteType.Integer);
            var pUnverified = cmd.Parameters.Add("$unverified", Microsoft.Data.Sqlite.SqliteType.Integer);
            var pMtime = cmd.Parameters.Add("$mtime", Microsoft.Data.Sqlite.SqliteType.Integer);
            var pGen = cmd.Parameters.Add("$gen", Microsoft.Data.Sqlite.SqliteType.Integer);
            foreach (var row in rows)
            {
                pDir.Value = row.Dir;
                pFiles.Value = row.DirectFiles;
                pSubdirs.Value = row.DirectSubdirs;
                pUnverified.Value = row.DirectUnverified;
                pMtime.Value = row.MtimeTicks;
                pGen.Value = generation;
                cmd.ExecuteNonQuery();
            }

            tx?.Commit();
        }
    }

    public IReadOnlyList<DirStat> QueryDirStats()
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                SELECT Dir, DirectFiles, DirectSubdirs, DirectUnverified, MtimeTicks, Generation
                FROM DirStats ORDER BY Dir;
                """;
            using var reader = cmd.ExecuteReader();
            var rows = new List<DirStat>();
            while (reader.Read())
            {
                rows.Add(new DirStat(
                    reader.GetString(0), reader.GetInt32(1),
                    reader.GetInt32(2), reader.GetInt32(3),
                    reader.GetInt64(4), reader.GetInt32(5)));
            }

            return rows;
        }
    }

    public void UpsertDeadLink(string path, string target)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                INSERT INTO DeadLinks(Path, Target) VALUES ($path, $target)
                ON CONFLICT(Path) DO UPDATE SET Target = excluded.Target;
                """;
            cmd.Parameters.AddWithValue("$path", path);
            cmd.Parameters.AddWithValue("$target", target);
            cmd.ExecuteNonQuery();
        }
    }

    public void DeleteDeadLink(string path)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = "DELETE FROM DeadLinks WHERE Path = $path;";
            cmd.Parameters.AddWithValue("$path", path);
            cmd.ExecuteNonQuery();
        }
    }

    public string? QueryDeadLink(string path)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = "SELECT Target FROM DeadLinks WHERE Path = $path;";
            cmd.Parameters.AddWithValue("$path", path);
            using var reader = cmd.ExecuteReader();
            return reader.Read() ? reader.GetString(0) : null;
        }
    }

    // P23: per-copy inventory facts for one duplicate set, so the
    // comparison UI orders and reasons from the record — never from
    // a render-time filesystem stat (TOCTOU) or the alphabetical
    // GROUP_CONCAT packing order.
    public IReadOnlyList<Fingerprint> QueryDuplicateMembers(string hash, int limit = 200)
    {
        lock (_gate)
        {
            using var cmd = _conn.CreateCommand();
            Enlist(cmd);
            cmd.CommandText = """
                SELECT Path, Size, MTimeUtcTicks, Hash, LastSeenGeneration,
                    Tier, Regrowth, AttrFlags, ClassGen
                FROM Fingerprints WHERE Hash = $hash
                ORDER BY Path LIMIT $limit;
                """;
            cmd.Parameters.AddWithValue("$hash", hash);
            cmd.Parameters.AddWithValue("$limit", Math.Clamp(limit, 1, 1000));
            using var reader = cmd.ExecuteReader();
            var rows = new List<Fingerprint>();
            while (reader.Read())
            {
                rows.Add(ReadFingerprint(reader));
            }

            return rows;
        }
    }

    public void Dispose()
    {
        if (_disposed)
        {
            return;
        }

        _disposed = true;
        EndBulk(commit: false); // Never leave a half-written run behind.
        _conn.Dispose();
    }
}
